    icon: "🏠",
    phrases: [
      { en: "This is old video. I saw it. I am sharing today", mr: "ꯃꯁꯤ ꯑꯔꯤꯕꯥ ꯚꯤꯗꯤꯑꯣꯅꯤ꯫ ꯑꯩꯅꯥ ꯎꯈꯤ꯫ ꯉꯁꯤ ꯑꯩꯍꯥꯛꯅꯥ ꯁꯦꯌꯔ ꯇꯧꯖꯔꯤ꯫", roman: "Yaha asalī vīḍiyo hai. maiṃne use dekhā| āja maiṃ sājhā karane jā rahā hū~", hint: "" },
      { en: "This is old video, yet I saw it so I am sharing today", mr: "ꯃꯁꯤ ꯑꯔꯤꯕꯥ ꯚꯤꯗꯤꯑꯣꯅꯤ, ꯑꯗꯨꯝ ꯑꯣꯏꯅꯃꯛ ꯑꯩꯍꯥꯛꯅꯥ ꯎꯈꯤ ꯃꯔꯝ ꯑꯗꯨꯅꯥ ꯉꯁꯤ ꯑꯩꯍꯥꯛꯅꯥ ꯁꯦꯌꯔ ꯇꯧꯔꯤ꯫", roman: "Yaha mūla vīḍiyo hai, hālā~ki maiṃne ise dekhā isalie maiṃ ise āja sājhā kara rahā hū~", hint: "" },
      { en: "This is old song. I heard it today", mr: "ꯃꯁꯤ ꯑꯔꯤꯕꯥ ꯏꯁꯩꯅꯤ꯫ ꯉꯁꯤ ꯑꯩꯍꯥꯛꯅꯥ ꯇꯥꯕꯥ ꯐꯪꯖꯔꯦ꯫", roman: "Yaha eka purānā gānā hai. maiṃne ise āja sunā.", hint: "" },
      { en: "Though it is old song, I heard it today", mr: "ꯑꯔꯤꯕꯥ ꯏꯁꯩ ꯑꯣꯏꯔꯕꯁꯨ ꯉꯁꯤꯗꯤ ꯇꯥꯕꯥ ꯐꯪꯖꯔꯦ꯫", roman: "Yaha eka purānā gānā hai lekina maiṃne ise āja sunā hai", hint: "" },
      { en: "My wife was standing there. He asked about girlfriend", mr: "ꯑꯩꯒꯤ ꯅꯨꯄꯤ ꯃꯐꯃꯗꯨꯗꯥ ꯂꯦꯞꯂꯝꯃꯤ꯫ ꯃꯍꯥꯛꯅꯥ ꯒꯦꯔꯂꯐ꯭ꯔꯦꯟꯗꯒꯤ ꯃꯔꯃꯗꯥ ꯍꯪꯈꯤ꯫", roman: "Merī patnī vahīṃ khar̤ī thī. usane garlaphreṃḍa ke bāre meṃ pūchā.", hint: "" },
      { en: "My wife was standing there yet he asked", mr: "ꯑꯩꯒꯤ ꯅꯨꯄꯤꯅꯥ ꯃꯐꯃꯗꯨꯗꯥ ꯂꯦꯞꯂꯝꯃꯤ ꯑꯗꯨꯕꯨ ꯃꯍꯥꯛꯅꯥ ꯍꯪꯈꯤ꯫", roman: "Merī patnī vahīṃ khar̤ī rahī lekina usane pūchā", hint: "" },
      { en: "Policeman was watching. He did not dare to run", mr: "ꯄꯨꯂꯤꯁꯃꯦꯟ ꯑꯃꯅꯥ ꯌꯦꯡꯂꯝꯃꯤ꯫ ꯃꯍꯥꯛ ꯂꯥꯟꯊꯦꯡꯅꯕꯒꯤ ꯊꯧꯅꯥ ꯂꯩꯈꯤꯗꯦ꯫", roman: "Eka pulisakarmī dekhatā rahā. usameṃ lar̤ane kī himmata nahīṃ thī.", hint: "" },
      { en: "As policeman was watching he did not dare", mr: "ꯄꯨꯂꯤꯁꯃꯦꯟꯅꯥ ꯌꯦꯡꯂꯤꯉꯩꯗꯥ ꯃꯍꯥꯛ ꯊꯧꯅꯥ ꯂꯩꯈꯤꯗꯦ꯫", roman: "Pulisakarmī ke dekhate rahane para usakī himmata nahīṃ huī", hint: "" },
      { en: "I had illusion of monsters coming", mr: "ꯑꯩꯉꯣꯟꯗꯥ ꯃꯅꯁ꯭ꯇꯔꯁꯤꯡ ꯂꯥꯀꯄꯒꯤ ꯏꯜꯌꯨꯁꯟ ꯂꯩꯔꯝꯃꯤ꯫", roman: "Mujhe rākṣasoṃ ke āne kā bhrama thā", hint: "" },
      { en: "Now she will search it forever", mr: "ꯍꯧꯖꯤꯛꯇꯤ ꯃꯍꯥꯛ ꯃꯇꯝ ꯆꯨꯞꯄꯗꯥ ꯊꯤꯖꯤꯅꯒꯅꯤ꯫", roman: "Aba vaha sadaiva khojatā rahegā", hint: "" },
      { en: "If we think of eating mango then..", mr: "ꯀꯔꯤꯒꯨꯝꯕꯥ ꯑꯩꯈꯣꯌꯅꯥ ꯑꯥꯝ ꯆꯥꯕꯒꯤ ꯃꯇꯥꯡꯗꯥ ꯈꯜꯂꯕꯗꯤ ꯃꯇꯝ ꯑꯗꯨꯗꯥ..", roman: "Agara hama āma khāne ke bāre meṃ soceṃ to...", hint: "" },
      { en: "If he decides to take revenge..", mr: "ꯀꯔꯤꯒꯨꯝꯕꯥ ꯃꯍꯥꯛꯅꯥ ꯔꯤꯚꯦꯟꯖ ꯇꯧꯅꯕꯥ ꯋꯥꯔꯦꯞ ꯂꯧꯔꯕꯗꯤ..", roman: "Agara usane badalā lene kā phaisalā kiyā..", hint: "" },
      { en: "I have decided a plan for tonight", mr: "ꯉꯁꯤꯒꯤ ꯅꯨꯃꯤꯗꯥꯡꯋꯥꯏꯔꯃꯒꯤ ꯊꯧꯔꯥꯡ ꯑꯃꯥ ꯑꯩꯅꯥ ꯂꯦꯄꯈ꯭ꯔꯦ꯫", roman: "Maiṃne āja rāta ke lie eka yojanā taya kara lī hai", hint: "" },
      { en: "I feel this way", mr: "ꯑꯩꯍꯥꯛꯅꯥ ꯑꯁꯤꯒꯨꯝꯕꯥ ꯃꯑꯣꯡꯗꯥ ꯐꯥꯑꯣꯏ꯫", roman: "Mujhe aisā lagatā hai.", hint: "" },
      { en: "I feel this", mr: "ꯃꯁꯤ ꯑꯩꯍꯥꯛꯅꯥ ꯐꯥꯑꯣꯏ꯫", roman: "Mujhe ye mahasūsa hotā hai.", hint: "" },
      { en: "He felt that I will not come", mr: "ꯑꯩꯍꯥꯛ ꯂꯥꯛꯂꯣꯏ ꯍꯥꯌꯅꯥ ꯃꯍꯥꯛꯅꯥ ꯐꯥꯑꯣꯈꯤ꯫", roman: "Use lagā maiṃ nahīṃ āūṃgā.", hint: "" },
      { en: "What do you feel?", mr: "ꯀꯔꯤ ꯐꯥꯑꯣꯔꯤꯕꯒꯦ?", roman: "Āpa kyā mahasūsa karate ho?", hint: "" },
      { en: "He felt happiness", mr: "ꯃꯍꯥꯛ ꯅꯨꯡꯉꯥꯏꯕꯥ ꯐꯥꯑꯣꯈꯤ꯫", roman: "Vaha khuśa thā", hint: "" },
      { en: "Don't you feel ashamed?", mr: "ꯅꯉꯅꯥ ꯂꯥꯡꯇꯛꯅꯕꯥ ꯐꯥꯑꯣꯗ꯭ꯔꯤꯕꯔꯥ?", roman: "Kyā tumheṃ śarma nahīṃ ātī?", hint: "" },
      { en: "Kaushik thinks he should go", mr: "ꯀꯧꯁꯤꯀꯅꯥ ꯃꯍꯥꯛ ꯆꯠꯀꯗꯕꯅꯤ ꯍꯥꯌꯅꯥ ꯈꯜꯂꯤ꯫", roman: "Kauśika socatā hai ki use jānā cāhie", hint: "" },
      { en: "He will feel bad", mr: "ꯃꯍꯥꯛ ꯐꯠꯇꯕꯥ ꯐꯥꯑꯣꯒꯅꯤ꯫", roman: "Use burā lagegā.", hint: "" },
      { en: "To show different aspects", mr: "ꯇꯣꯉꯥꯟ-ꯇꯣꯉꯥꯅꯕꯥ ꯃꯁꯀꯁꯤꯡ ꯎꯠꯅꯕꯥ꯫", roman: "Vibhinna viśeṣatāeṃ dikhāne ke lie.", hint: "" },
      { en: "To follow up & pressurize", mr: "ꯐꯣꯂꯣ ꯑꯞ ꯇꯧꯅꯕꯥ & ꯄ꯭ꯔꯦꯁꯔ ꯄꯤꯅꯕꯥ꯫", roman: "Phaॉloapa karane aura dabāva banāne ke lie.", hint: "" },
      { en: "Every home same story", mr: "ꯌꯨꯝ ꯈꯨꯗꯤꯡꯃꯛ ꯆꯞ ꯃꯥꯟꯅꯕꯥ ꯋꯥꯔꯤ꯫", roman: "Hara ghara kī yahī kahānī hai.", hint: "" },
      { en: "To approve formally", mr: "ꯐꯣꯔꯃꯦꯜ ꯑꯣꯏꯅꯥ ꯑꯌꯥꯕꯥ ꯄꯤꯅꯕꯥ꯫", roman: "Aupacārika rūpa se anumodana karanā", hint: "" },
      { en: "To cause destruction", mr: "ꯃꯥꯡꯍꯟ ꯇꯥꯀꯍꯅꯕꯥ꯫", roman: "Brahmāṇḍa kā vināśa.", hint: "" },
      { en: "Repeat like tape", mr: "ꯇꯦꯄꯒꯨꯝꯅꯥ ꯍꯟꯖꯤꯟ ꯍꯟꯖꯤꯟ ꯇꯧ꯫", roman: "Ṭepa kī taraha doharāe~.", hint: "" },
      { en: "To force to do", mr: "ꯇꯧꯅꯕꯥ ꯐꯣꯔꯁ ꯇꯧꯕꯥ꯫", roman: "Aisā karane ke lie majabūra kiyā gayā.", hint: "" },
      { en: "No control on tongue", mr: "ꯂꯣꯂꯗꯥ ꯀꯟꯠꯔꯣꯜ ꯇꯧꯕꯥ ꯂꯩꯇꯦ꯫", roman: "Bhāṣā para koī niyaṃtraṇa nahīṃ hai.", hint: "" },
      { en: "Not utter a word", mr: "ꯋꯥꯍꯩ ꯑꯃꯠꯇꯥ ꯐꯣꯡꯗꯣꯀꯄꯥ ꯅꯠꯇꯦ꯫", roman: "Eka śabda bhī nahīṃ bolā jātā.", hint: "" }
    ]
